import{_ as t,o as s,c as o,a3 as p}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"仓库相关优先级现象","description":"","frontmatter":{"translationSource":{"title":"仓库相关优先级现象","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}]]},"headers":[],"relativePath":"zh/depot-related-priority-phenomena.md","filePath":"zh/page-pgnaI2HtL8UdrJqoloJQvA.md"}'),a={name:"zh/depot-related-priority-phenomena.md"};function r(n,e,d,i,l,g){return s(),o("div",null,[...e[0]||(e[0]=[p('<div class="logistics-content"><h1 id="仓库相关优先级现象" tabindex="-1">仓库相关优先级现象 <a class="header-anchor" href="#仓库相关优先级现象" aria-label="Permalink to &quot;仓库相关优先级现象&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>pgnaI2HtL8UdrJqoloJQvA</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5922f12e457a433.q90-04b897c52e14153c.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-fd14ff7c64c73e3f.q90-e2565d9429a53c5e.webp" alt="图片"></td></tr></tbody></table><p>该结构中，将两个仓库取货口AB与其中一个A连接的传送带重放，会使得A优先。</p><p>单独重放取货口可能使其进入低优先状态，但是无法稳定达到，无法确定结果与所需次数，也就是基本上是随机的出现优先级问题。</p><p>经测试，该现象（取货口优先级）几乎总是会在下线后被修正，通常可以忽略，然而无法稳定该结论，甚至有时下线反而会引发该问题</p><p>不确定反应池是否有类似现象（取货口优先级）。</p><p>仓库存货口存在与反应池相同的优先输入现象，具体为先连接先输入。</p><p>此外协议核心亦有相同现象（取货口优先级、存货口优先级），该现象可能是稳定的。</p><p>26年11月 by13x286 根据我在存货口的研究揣测一下优先级形成的原因：（取货口部分不保真，只是一种猜想）</p><p>1.整个基建结算并不是同步的，在代码层面可能是顺序进行，仓库存取货由于存入物品常常混带因此没有做多线程处理，但取货口完全可能进行额外的同类物品分组处理</p><p>2.为了节省计算资源，核心未使用的存取货口以及未连接传送带或物流器的仓库口不参与结算</p><p>3.传送带是一整根作为一件设备结算(根据占用设备压力等推算）</p><p>所以，推测<strong>存货口</strong>优先级机制等效为：当仓库存货口或核心存货口连接传送带或物流器时，获得一个编号；同一时刻结算入库时，按照编号顺序依次结算。</p><p>因此在重新放置存货口或修改紧连存货口的传送带或物流器都会导致其重新获得编号，进而优先级改变。但传送带或物流器的另一头无论连与不连是否更改都不影响存货口的优先级。</p><p>但<strong>取货口</strong>的机制却大不相同，如果从存货口的推测出发，常态下的取货口机制可能是轮询，实现方式类似：给所有，证据就是在常态下空仓三个出货口1 2 3，取货口轮询，单带入库时取货顺序1 2 3用传送带向仓库入库两个物品出货口为1 2，同时用三带向仓库入库出货为1 2 3，再向仓库入库一个物品出货为3，这意味着取货口具备跨周期跨长时间间隔的轮询功能，也就是猜测的计数编号。</p><p>在此基础上首先怀疑如何确定取货口的初始编号？不难想出当然是通过检索目前场上已有的取货口编号再进行处理，进行实验同优先级轮询ABCD，新放置的出货口优先级会是倒数第一即ABCDE(为什么不说是正数第一呢，因为当轮循环E就会输出，如果是正数第一那么连放EF应该是ABCDFEABCD，但实际是ABCDEFABCD)。同时如果在物品出取货口半格时删除传送带会导致下一个口被跳过，<strong>猜测是ABCDE删除C后下一个指针指向第四个但C被删除导致指向E，D被跳过</strong></p><p>这时我想到，根据上文稳定获得取货口A优先的方法放置了两个独立的AB组并成功发现两个A(优先)独立轮询，删除两个A后两个B独立轮询，这进一步说明取货口的优先机制很可能<s>是</s>设计之外的bug而不是特性<s>就是特性</s>，<strong>当场上已有普通出货口C时无法形成AB优先级(但已有A优先后BC理论同级，却仍然可以继续形成A2优先),</strong><s>包括其他基地，包括谷地，</s><strong>当其他基地已有普通出货口C时AB优先级操作会使得B获得优先级，且此时BC以及后续摆放的出货口都与BC同级</strong>，此怀疑继承场上取货口编号时出了问题导致优先级的形成，而有了C锚定编号bug有所变化。</p><p>既然发现了优先级与场上是否有出货口有关，那么构成优先级的操作A取货口A传送带B取货口M移动之中每一项都是必要的吗，进行实验后发现<strong>B取货口是相对不重要</strong>的，只要场上没有<strong>常态取货口，<strong>同时移动</strong>A取货口+A传送带</strong>就能构成Ａ优先，且后续放置的所有普通取货口都是低优先。但当其他基地有普通Ｃ想要Ｂ获得优先时，必须保证<strong>A取A传B取同时</strong>，且有概率Ａ优先或ABC同时<strong>高优先</strong>(再做一组AB可知与A优先相同)，且仅此时Ｂ取是不能替换为Ｂ传的，怀疑和补充实验中的移动异常出货有关</p><p>这里明确一下，<strong>优先只有高和低</strong>两种，没有第三级的优先级，同优先下轮询会有顺序但和优先级是两码事。</p><p>整理一下，把轮询比作格子，那么指针就是指向第几个格子的箭头当3出货且没到下一个4出货时删除3（实际上删除12都可以，主要是卡准时间点），出货口4将会被跳过。因为关闭取货口也不会影响优先级，且保留出货顺序。由此可知指针重置的判断和出货口数量直接挂钩</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1d4479d6f280c0cb.png" alt="仓库相关优先级现象"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-81427ebe166c38b0.png" alt="仓库相关优先级现象"></p><p>同时我们要明确，优先口只是优先，普通口在仓库有物品时也会出货，先前我们已经明确了优先口之间有轮询，拆除优先口之后普通口之间有轮询，那么在保留优先口时普通口之间会有轮询吗？</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-45c28e1f5b971fcb.png" alt="仓库相关优先级现象"></p><p>这给了指针说一个沉重的打击，即便中间穿插输入2重置，普通口依然保持均匀轮询，但众所周知乌云的事可以先放放，这里我们提出指针是配合计数编号的，指针指到会使计数编号加一。</p><p>这是突然想到，简制手册中包含有各类植物的消耗，正如集成援助活动中官方统计原材料消耗一样，计数编号配合指针方便跨时间周期记录循环顺序和当前位置显然是更合理的理论。</p><p><s>怀疑AB形成优先级的操作使得B的优先级计数编号过低，低于总出货口数量导致指针指不到B以及后面放置的B-1等等，实验AB优先级后删除B再放置C，C无法继承A的高优先级，AC之间仍有优先级 猜测错误</s></p><p>~~怀疑AB形成优先级的操作使得A的优先级计数编号过高，指针从最高往下数数所有指不到B以及后面放置的B-1等等，实验暂无，没想好怎么构建。~~放弃完全指针的猜想，并非指不到只是不优先指，猜测可能和优化性能时的操作耦合了，比如说这一刻仓库里有3个物品指针向后找3个有效出口，这时这个操作可能跳过指针重置，或者说指针重置是假的机制，实际上输出之后自动在同优先级下置后也就是这样，也能实现标准均匀轮询。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-521e4976b825c6e9.png" alt="仓库相关优先级现象"></p><p><strong>一些补充实验：</strong></p><p>在已有A优先的情况下放置和复制取货口都将低于A优先无法出货，但m键移动时会在当次循环的末端出货一次然后无法再次出货，疑似取货口优先与m键移动有关，m按下后取消不算做移动。</p><p>在使用m移动的某种神秘情景下，空仓单带入库，AB出库，会形成一种奇特的每入库两个物品，AB同时出库，已经确定的是仓库没有对应物品缓存，AB实际速率皆为1/2，该状态形成后跨客户端跨设备跨离线保留，甚至抗一定程度的入库速率波动，<strong>疑似有没控制好的变量，暂时搁置</strong>。</p><p>编号灵感来源方舟本家的早期的仇恨机制(每个干员有一个固定大数<em>仇恨等级+时间构成的仇恨值，例如10000</em>仇恨等级+创建时间，以此来保证敌方优先攻击仇恨高的其次攻击更晚下场的，由于早期对创建时间的范围做了限制，以及创建时间每三帧+1，因此在创建时间过长或创建时间过近时会导致仇恨值相同敌人攻击靠前部署的编号更小的干员）无论终末地沿用类似的逻辑还是使用修正bug后的新逻辑，这都给了我们一个研究底层机制的线头，让我们一窥背后复杂的bug与机制。</p></div>',1)])])}const m=t(a,[["render",r]]);export{h as __pageData,m as default};
